package org.solaris.receiver;
import android.content.*;import android.media.projection.MediaProjection;import org.webrtc.*;import org.json.*;import java.util.*;import java.util.function.Consumer;import java.util.concurrent.*;
final class ScreenEngine {
 private final Context context;private final BroadcastSignals signals;private JSONObject scope;private volatile boolean closed;private final Consumer<JSONObject> emit;private final ScheduledExecutorService queue=Executors.newSingleThreadScheduledExecutor();private final Map<String,Node> peers=new HashMap<>();
 private final EglBase egl;private final PeerConnectionFactory factory;private ScreenCapturerAndroid capture;private VideoSource source;private VideoTrack track;private SurfaceTextureHelper helper;private String id;private JSONObject options;private List<PeerConnection.IceServer> ice=new ArrayList<>();
 private static final class Node{String viewer,broadcast,connection=UUID.randomUUID().toString();PeerConnection pc;boolean ready;String offer;JSONObject quality;long seen=System.currentTimeMillis();List<IceCandidate> pending=new ArrayList<>();Node(String v){viewer=v;}}
 ScreenEngine(Context c,DiskBridge disk,Consumer<JSONObject> out){context=c;emit=out;
 signals=new BroadcastSignals(new BroadcastSignals.Vault(){public JSONObject load()throws Exception{Object raw=disk.command("vaultGet",new JSONObject().put("key","session"));return raw==null?null:new JSONObject((String)raw);}public void save(JSONObject value)throws Exception{disk.command("vaultSet",new JSONObject().put("key","session").put("value",value.toString()));}},new BroadcastSignals.Listener(){public void snapshot(String broadcast,JSONObject value){post(()->{if(Objects.equals(id,broadcast))prune(value);});}public void signal(JSONObject value){post(()->incoming(value));}public void ended(String broadcast,String reason){post(()->{if(!Objects.equals(id,broadcast))return;String old=id;stopInternal();try{emit.accept(new JSONObject().put("type","media-ended").put("id",old).put("error",reason));}catch(Exception ignored){}});}public void error(Exception error){peerError(error);}});PeerConnectionFactory.initialize(PeerConnectionFactory.InitializationOptions.builder(c).createInitializationOptions());egl=EglBase.create();queue.scheduleAtFixedRate(()->{for(Iterator<Node> it=peers.values().iterator();it.hasNext();){Node n=it.next();if(System.currentTimeMillis()-n.seen>45000){n.pc.close();n.pc.dispose();it.remove();}}},5,5,TimeUnit.SECONDS);factory=PeerConnectionFactory.builder().setVideoEncoderFactory(new DefaultVideoEncoderFactory(egl.getEglBaseContext(),true,true)).setVideoDecoderFactory(new DefaultVideoDecoderFactory(egl.getEglBaseContext())).createPeerConnectionFactory();}
 void start(Intent permission,JSONObject a,java.util.function.Consumer<Exception> ready){post(()->{try{stopInternal();scope=a.getJSONObject("scope");id=a.getString("id");options=a.getJSONObject("quality");ice=new ArrayList<>();JSONArray list=a.optJSONArray("iceServers");if(list!=null)for(int i=0;i<list.length();i++){JSONObject s=list.getJSONObject(i);List<String> urls=new ArrayList<>();Object u=s.get("urls");if(u instanceof JSONArray){JSONArray arr=(JSONArray)u;for(int j=0;j<arr.length();j++)urls.add(arr.getString(j));}else urls.add((String)u);ice.add(PeerConnection.IceServer.builder(urls).setUsername(s.optString("username")).setPassword(s.optString("credential")).createIceServer());}
 source=factory.createVideoSource(true);helper=SurfaceTextureHelper.create("SolarisScreen",egl.getEglBaseContext());final String captureId=id;capture=new ScreenCapturerAndroid(permission,new MediaProjection.Callback(){@Override public void onStop(){post(()->{if(!Objects.equals(id,captureId))return;String old=id;stopInternal();try{emit.accept(new JSONObject().put("type","media-ended").put("id",old));}catch(Exception ignored){}});}});capture.initialize(helper,context,source.getCapturerObserver());capture.startCapture(options.optInt("width",1920),options.optInt("height",1080),options.optInt("fps",60));track=factory.createVideoTrack("solaris-screen",source);signals.start(a);ready.accept(null);
 }catch(Exception e){stopInternal();ready.accept(e);}});}
 void command(String command,JSONObject a){post(()->{try{if(id==null||!id.equals(a.optString("id")))return;String viewer=a.optString("viewerID");Node n=peers.get(viewer);if(command.equals("mediaJoin")||command.equals("mediaRecover")){if(n!=null){if(command.equals("mediaJoin")){n.seen=System.currentTimeMillis();if(n.offer!=null)signal(n,new JSONObject().put("type","native-offer").put("sdp",n.offer));return;}if(!n.connection.equals(a.optString("connectionID")))return;peers.remove(viewer);n.pc.close();n.pc.dispose();}if(peers.size()>=5)throw new Exception("시청자는 최대 5명입니다.");join(viewer);return;}if(n==null||!n.connection.equals(a.optString("connectionID")))return;n.seen=System.currentTimeMillis();if(command.equals("mediaAnswer")){n.pc.setRemoteDescription(new Observer(){@Override public void onSetSuccess(){post(()->{if(peers.get(n.viewer)!=n)return;n.ready=true;for(IceCandidate c:n.pending)n.pc.addIceCandidate(c);n.pending.clear();});}},new SessionDescription(SessionDescription.Type.ANSWER,a.getString("sdp")));}else if(command.equals("mediaIce")){IceCandidate c=new IceCandidate(a.optString("sdpMid","0"),a.optInt("sdpMLineIndex"),a.getString("candidate"));if(n.ready)n.pc.addIceCandidate(c);else if(n.pending.size()<128)n.pending.add(c);}else if(command.equals("mediaLeave")){peers.remove(viewer);n.pc.close();n.pc.dispose();}else if(command.equals("mediaQuality")){quality(n,a.optJSONObject("quality"));}}catch(Exception e){peerError(e);}});}
 private void join(String viewer)throws Exception{Node n=new Node(viewer);n.broadcast=id;PeerConnection.RTCConfiguration c=new PeerConnection.RTCConfiguration(ice);c.sdpSemantics=PeerConnection.SdpSemantics.UNIFIED_PLAN;n.pc=factory.createPeerConnection(c,new PeerConnection.Observer(){public void onSignalingChange(PeerConnection.SignalingState s){}public void onIceConnectionChange(PeerConnection.IceConnectionState s){}public void onIceConnectionReceivingChange(boolean r){}public void onIceGatheringChange(PeerConnection.IceGatheringState s){}public void onIceCandidate(IceCandidate x){try{signal(n,new JSONObject().put("type","native-ice").put("candidate",new JSONObject().put("candidate",x.sdp).put("sdpMid",x.sdpMid).put("sdpMLineIndex",x.sdpMLineIndex)));}catch(Exception e){failure(e);}}public void onIceCandidatesRemoved(IceCandidate[] c){}public void onAddStream(MediaStream s){}public void onRemoveStream(MediaStream s){}public void onDataChannel(DataChannel d){d.close();}public void onRenegotiationNeeded(){}public void onAddTrack(RtpReceiver r,MediaStream[] s){} });if(n.pc==null)throw new Exception("WebRTC 생성 실패");peers.put(viewer,n);n.pc.addTrack(track,List.of("solaris"));quality(n,options);n.pc.createOffer(new Observer(){@Override public void onCreateSuccess(SessionDescription s){post(()->{if(peers.get(n.viewer)!=n)return;n.pc.setLocalDescription(new Observer(){@Override public void onSetSuccess(){post(()->{if(peers.get(n.viewer)!=n)return;try{n.offer=s.description;signal(n,new JSONObject().put("type","native-offer").put("sdp",s.description));}catch(Exception e){peerError(e);}});}},s);});}},new MediaConstraints());}
 private void quality(Node n,JSONObject q){if(q==null)return;int fps=Math.max(15,Math.min(60,q.optInt("fps",60))),w=Math.max(640,Math.min(2560,q.optInt("width",1920))),h=Math.max(360,Math.min(1440,q.optInt("height",1080)));n.quality=q;int sharedW=w,sharedH=h,sharedFPS=fps;for(Node other:peers.values())if(other.quality!=null){sharedW=Math.min(sharedW,other.quality.optInt("width",w));sharedH=Math.min(sharedH,other.quality.optInt("height",h));sharedFPS=Math.min(sharedFPS,other.quality.optInt("fps",fps));}source.adaptOutputFormat(sharedW,sharedH,sharedFPS);for(RtpSender sender:n.pc.getSenders()){RtpParameters p=sender.getParameters();for(RtpParameters.Encoding e:p.encodings){e.maxBitrateBps=Math.max(2000000,Math.min(30000000,q.optInt("mbps",12)*1000000));e.maxFramerate=fps;}sender.setParameters(p);}}
 private void signal(Node n,JSONObject payload){post(()->{if(peers.get(n.viewer)!=n||!Objects.equals(id,n.broadcast))return;try{payload.put("broadcast",n.broadcast).put("connectionID",n.connection);signals.send(n.broadcast,n.viewer,payload);emit.accept(new JSONObject().put("type","media-signal").put("id",n.broadcast).put("viewerID",n.viewer).put("payload",payload));}catch(Exception e){peerError(e);}});}
 private void peerError(Exception e){try{emit.accept(new JSONObject().put("type","media-peer-error").put("id",id).put("error",e.getMessage()));}catch(Exception ignored){}}
 private void failure(Exception e){try{emit.accept(new JSONObject().put("type","media-ended").put("id",id).put("error",e.getMessage()));}catch(Exception ignored){}}
 void status(Consumer<JSONObject> callback){post(()->{try{JSONArray list=new JSONArray();for(Node n:peers.values())list.put(new JSONObject().put("viewerID",n.viewer).put("connectionID",n.connection));callback.accept(new JSONObject().put("id",id==null?JSONObject.NULL:id).put("active",id!=null&&track!=null).put("nativeSignaling",true).put("peers",list));}catch(JSONException e){peerError(e);}});}
 void stop(){post(this::stopInternal);}
 void close(){closed=true;signals.close();queue.execute(()->{stopInternal();factory.dispose();egl.release();queue.shutdown();});}
 private void stopInternal(){signals.stop();id=null;for(Node n:peers.values()){n.pc.close();n.pc.dispose();}peers.clear();if(capture!=null){capture.stopCapture();capture.dispose();capture=null;}if(track!=null){track.dispose();track=null;}if(source!=null){source.dispose();source=null;}if(helper!=null){helper.dispose();helper=null;}}

 private void post(Runnable operation){if(closed)return;try{queue.execute(()->{if(!closed)operation.run();});}catch(RejectedExecutionException ignored){}}
 private void incoming(JSONObject envelope){try{JSONObject p=envelope.getJSONObject("payload");if(id==null||!id.equals(p.optString("broadcast")))return;String type=p.optString("type"),command=switch(type){case "media-join"->"mediaJoin";case "media-recover"->"mediaRecover";case "media-leave"->"mediaLeave";case "media-heartbeat"->"mediaHeartbeat";case "media-quality"->"mediaQuality";case "native-answer"->"mediaAnswer";case "native-ice"->"mediaIce";default->null;};if(command==null)return;JSONObject args=new JSONObject(p.toString()).put("id",id).put("viewerID",envelope.getString("sender"));JSONObject candidate=p.optJSONObject("candidate");if(candidate!=null){for(Iterator<String> keys=candidate.keys();keys.hasNext();){String key=keys.next();args.put(key,candidate.get(key));}}command(command,args);}catch(Exception e){peerError(e);}}
 private void prune(JSONObject snapshot){if(id==null||scope==null)return;Set<String> allowed=new HashSet<>();try{if(scope.getString("kind").equals("direct")){JSONArray sessions=snapshot.optJSONArray("sessions");if(sessions!=null)for(int i=0;i<sessions.length();i++){JSONObject session=sessions.getJSONObject(i);if(scope.getString("id").equals(session.optString("id"))&&"accepted".equals(session.optString("state"))){allowed.add(session.getString("a"));allowed.add(session.getString("b"));}}}else{String server=null;JSONArray channels=snapshot.optJSONArray("channels");if(channels!=null)for(int i=0;i<channels.length();i++){JSONObject channel=channels.getJSONObject(i);if(scope.getString("id").equals(channel.optString("id")))server=channel.getString("server_id");}JSONArray members=snapshot.optJSONArray("members");if(members!=null)for(int i=0;i<members.length();i++){JSONObject member=members.getJSONObject(i);if(Objects.equals(server,member.optString("server_id")))allowed.add(member.getJSONObject("profile").getString("uid"));}}for(Iterator<Node> nodes=peers.values().iterator();nodes.hasNext();){Node n=nodes.next();if(!allowed.contains(n.viewer)){n.pc.close();n.pc.dispose();nodes.remove();}}}catch(Exception e){peerError(e);}}
 private class Observer implements SdpObserver{public void onCreateSuccess(SessionDescription s){}public void onSetSuccess(){}public void onCreateFailure(String e){peerError(new Exception(e));}public void onSetFailure(String e){peerError(new Exception(e));}}
}
